import java.io.InputStream;
import java.io.OutputStream;
import java.io.PrintWriter;
import java.io.IOException;

public class Main {
    public static void main(String[] args) {
        InputStream is = System.in;
        OutputStream os = System.out;
        InputReader in = new InputReader(is);
        PrintWriter out = new PrintWriter(os);
        int n = in.nextInt();
        int m = in.nextInt();
        int k = in.nextInt();
        long mod = 998244353;
        int lim = Math.min(n, k);
        long[][] dp = new long[k + 1][lim + 1];
        dp[0][0] = 1;
        for (int i = 1; i <= k; i++) {
            for (int j = 1; j <= lim; j++) {
                dp[i][j] = (dp[i - 1][j] * j % mod + dp[i - 1][j - 1] * (n - j + 1) % mod) % mod;
            }
        }
        long invm = modPow(m, mod - 2, mod);
        long res = 0;
        long[] pow = new long[lim + 1];
        pow[0] = 1;
        for (int i = 1; i <= lim; i++) {
            pow[i] = pow[i - 1] * invm % mod;
        }
        for (int i = 0; i <= lim; i++) {
            res = (res + dp[k][i] * pow[i] % mod) % mod;
        }
        out.println(res);
        out.close();
    }

    static long modPow(long a, long e, long mod) {
        long r = 1;
        while (e > 0) {
            if ((e & 1) == 1) r = r * a % mod;
            a = a * a % mod;
            e >>= 1;
        }
        return r;
    }

    static class InputReader {
        private InputStream stream;
        private byte[] buf = new byte[1024];
        private int curChar;
        private int numChars;

        public InputReader(InputStream stream) {
            this.stream = stream;
        }

        public int read() {
            if (numChars == -1) throw new RuntimeException();
            if (curChar >= numChars) {
                curChar = 0;
                try {
                    numChars = stream.read(buf);
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
                if (numChars <= 0) return -1;
            }
            return buf[curChar++];
        }

        public int nextInt() {
            int c = read();
            while (c <= ' ') c = read();
            int sgn = 1;
            if (c == '-') { sgn = -1; c = read(); }
            int res = 0;
            do {
                if (c < '0' || c > '9') throw new RuntimeException();
                res = res * 10 + (c - '0');
                c = read();
            } while (c > ' ');
            return res * sgn;
        }
    }
}
